    if (this == U_UNEXPECTED_TOKEN) return "UErrorCode.U_UNEXPECTED_TOKEN, UErrorCode.U_FMT_PARSE_ERROR_START";
    if (this == U_MULTIPLE_DECIMAL_SEPARATORS)
      return "UErrorCode.U_MULTIPLE_DECIMAL_SEPARATORS, UErrorCode.U_MULTIPLE_DECIMAL_SEPERATORS";
    if (this == U_BRK_INTERNAL_ERROR) return "UErrorCode.U_BRK_INTERNAL_ERROR, UErrorCode.U_BRK_ERROR_START";
    if (this == U_REGEX_INTERNAL_ERROR) return "UErrorCode.U_REGEX_INTERNAL_ERROR, UErrorCode.U_REGEX_ERROR_START";
    if (this == U_IDNA_PROHIBITED_ERROR)
      return "UErrorCode.U_IDNA_PROHIBITED_ERROR, UErrorCode.U_IDNA_ERROR_START, UErrorCode.U_STRINGPREP_PROHIBITED_ERROR";
    if (this == U_IDNA_UNASSIGNED_ERROR)
      return "UErrorCode.U_IDNA_UNASSIGNED_ERROR, UErrorCode.U_STRINGPREP_UNASSIGNED_ERROR";
    if (this == U_IDNA_CHECK_BIDI_ERROR)
      return "UErrorCode.U_IDNA_CHECK_BIDI_ERROR, UErrorCode.U_STRINGPREP_CHECK_BIDI_ERROR";
    if (this == U_PLUGIN_ERROR_START) return "UErrorCode.U_PLUGIN_ERROR_START, UErrorCode.U_PLUGIN_TOO_HIGH";
    return super.toString();
  }
}
